import React from "react";

function SlotCard({ slot }) {
  const isOccupied = slot.status === "occupied";
  const bgColor = isOccupied ? "#ff4d4d" : "#4CAF50"; // red/green

  return (
    <div
      style={{
        backgroundColor: bgColor,
        color: "#fff",
        borderRadius: "8px",
        padding: "16px",
        width: "220px",
        margin: "10px",
        textAlign: "center",
        boxShadow: "0 2px 6px rgba(0,0,0,0.2)",
      }}
    >
      <h3>Slot {slot.slot}</h3>
      <p>Status: {slot.status}</p>
      <p>Last Plate: {slot.plate || "-"}</p>
      <p>
        Time: {slot.time ? new Date(slot.time).toLocaleTimeString() : "-"}
      </p>
    </div>
  );
}

export default SlotCard;
